  messages: [
    {
      role: 'system',
      content: 'You are ResearchAgent. Return ONLY JSON: {"research":{"notes":["string"],"sources":[{"title":"string","url":"string","snippet":"string"}],"citations":["string"],"gaps":["string"],"confidence":"high|medium|low"}}'
    },
    {
      role: 'user',
